def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter
    bg = Counter(x for row in grid for x in row).most_common(1)[0][0]

    candidates = []
    for axis, n, m in ((0, h, w), (1, w, h)):
        lines = []
        for i in range(n):
            vals = [grid[i][j] for j in range(w)] if axis == 0 else [grid[j][i] for j in range(h)]
            if len(set(vals)) == 1 and vals[0] != bg:
                lines.append(i)
        if not lines:
            continue

        if len(lines) > 1:
            diffs = [lines[k + 1] - lines[k] for k in range(len(lines) - 1)]
            import math
            period = diffs[0]
            for d in diffs[1:]:
                period = math.gcd(period, d)
        else:
            period = lines[0] + 1
        if period <= 0:
            continue

        def get(i, j):
            return grid[i][j] if axis == 0 else grid[j][i]

        def is_divider(pos):
            return pos in lines

        starts = list(range(0, n, period))
        best_start, best_score = 0, -1
        for start in starts:
            score = 0
            for r in range(min(period, n - start)):
                pos = start + r
                if is_divider(pos):
                    continue
                for c in range(m):
                    val = get(pos, c)
                    if val != bg:
                        score += 1
            if score > best_score:
                best_score, best_start = score, start
        candidates.append((best_score, axis, period, best_start, lines))

    if not candidates:
        return [row[:] for row in grid]

    _, axis, period, source_start, lines = max(candidates, key=lambda x: x[0])
    out = [row[:] for row in grid]
    n, m = (h, w) if axis == 0 else (w, h)

    def get(i, j):
        return out[i][j] if axis == 0 else out[j][i]

    def setv(i, j, value):
        if axis == 0:
            out[i][j] = value
        else:
            out[j][i] = value

    for start in range(0, n, period):
        if start == source_start:
            continue
        length = min(period, n - start)
        for r in range(length):
            dest_pos = start + r
            src_pos = source_start + r
            if dest_pos in lines or src_pos >= n or src_pos in lines:
                continue
            for c in range(m):
                src_val = get(src_pos, c)
                if src_val != bg and get(dest_pos, c) == bg:
                    setv(dest_pos, c, src_val)

    return out
